// windvane: /windvane-export writes the project's memory out as files.
//
// The engine does the work, `python -m windvane.export --project <cwd>`,
// and prints one JSON line naming the files it wrote (`written`, or `paths`
// / `files`); the command lists them. An engine that prints one path per
// line instead is read the same way.
//
// register.ts registers the command and hooks its run; this module never
// holds `$`.
import { clip, engineEnv, lastJsonLine, pythonHint, type Host } from './engine'

const EXPORT_TIMEOUT_MS = 120_000

// Registered at session.start by register.ts.
export const EXPORT_COMMAND = {
  name: 'windvane-export',
  description: "windvane: export this project's memory, rules and checkpoints to files",
}

// The paths a run wrote: the JSON line's list, else stdout's lines.
export function pathsOf(stdout: string, reply: Record<string, unknown> | undefined): string[] {
  if (reply) {
    for (const key of ['written', 'paths', 'files']) {
      const v = reply[key]
      if (Array.isArray(v)) return v.filter((p): p is string => typeof p === 'string' && p !== '')
    }
    return []
  }
  return stdout
    .split('\n')
    .map(l => l.trim())
    .filter(Boolean)
}

// The command's answer.
export async function exportProject(host: Host, configured: string): Promise<string> {
  const python = await host.python(configured)
  const store = await host.store()
  const project = await host.cwd()
  let run
  try {
    run = await host.run([python, '-m', 'windvane.export', '--project', project], {
      cwd: project,
      env: engineEnv(host.pluginRoot, store),
      timeoutMs: EXPORT_TIMEOUT_MS,
    })
  } catch (err) {
    return `Not exported: ${pythonHint(python, err)}`
  }
  const reply = lastJsonLine(run.stdout)
  if (run.exitCode !== 0 || typeof reply?.error === 'string') {
    const why = (typeof reply?.error === 'string' && reply.error) || clip(run.stderr, 200) || `exit ${run.exitCode}`
    return `Not exported: ${why}`
  }
  const paths = pathsOf(run.stdout, reply)
  if (paths.length === 0) return 'Nothing exported: the project holds nothing to write.'
  return [`Exported ${paths.length} file${paths.length === 1 ? '' : 's'}:`, ...paths.map(p => `  ${p}`)].join('\n')
}

files.hooks/import.ts:
// windvane: /windvane-import brings an existing store's records into
// windvane's.
//
// The engine does the work, `python -m windvane.migrate --import`, and
// prints one JSON line, `{"copied": N, "skipped": N, "dst": "<store>"}` or
// `{"error": "..."}`; the command shows the counts or the error.
//
// register.ts registers the command and hooks its run; this module never
// holds `$`.
import { clip, engineEnv, lastJsonLine, pythonHint, type Host } from './engine'

const IMPORT_TIMEOUT_MS = 300_000

// Registered at session.start by register.ts.
export const IMPORT_COMMAND = {
  name: 'windvane-import',
  description: "windvane: import an existing store's memories, rules and checkpoints",
}

// The reply in one line: "copied N, skipped N into <dst>".
export function importLine(reply: Record<string, unknown>): string {
  const n = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0)
  const dst = typeof reply.dst === 'string' && reply.dst ? ` into ${reply.dst}` : ''
  return `copied ${n(reply.copied)}, skipped ${n(reply.skipped)}${dst}`
}

// The command's answer.
export async function importStore(host: Host, configured: string): Promise<string> {
  const python = await host.python(configured)
  const store = await host.store()
  let run
  try {
    run = await host.run([python, '-m', 'windvane.migrate', '--import'], {
      env: engineEnv(host.pluginRoot, store),
      timeoutMs: IMPORT_TIMEOUT_MS,
    })
  } catch (err) {
    return `Not imported: ${pythonHint(python, err)}`
  }
  const reply = lastJsonLine(run.stdout)
  if (run.exitCode !== 0 || !reply || typeof reply.error === 'string') {
    const why = (typeof reply?.error === 'string' && reply.error) || clip(run.stderr, 200) || `exit ${run.exitCode}`
    return `Not imported: ${why}`
  }
  return `Imported: ${importLine(reply)}`
}

files.hooks/ledger.ts:
// windvane: the per-project token and cost ledger, recorded by the machine
// so nobody has to write it down.
//
// Every main-loop turn.complete adds the turn's usage (TurnUsage: the four
// token counts as the API reports them) to $.store under
// `ledger:<the folder the session was opened in>:<YYYY-MM-DD>` (the local
// day), with a turn count
// and the cost: the session's own priced total ($.session.usage().cost.usd)
// since the previous main turn, so a subagent's spend lands on the turn that
// waited for it. Subagent turns are not counted on their own (their tokens
// are in the session's cost, not in the token columns). A turn that counted
// nothing (an interrupt, an API error: no usage) adds no entry, and a shell
// cd during the session does not move the project.
//
// /windvane-cost prints today's totals for this project, this project's
// totals over every recorded day, and today's over every project.
//
// register.ts holds every hook (session.start, turn.complete and the
// command's run) and the store writes, built on the plain functions here and
// the report; this module never holds `$`.
import type { CommandSpec, TurnUsage } from 'claude-code'
import type { Host } from './engine'
import { normalizePath } from './ring'

const PREFIX = 'ledger:'

export const LEDGER_COMMAND: CommandSpec = {
  name: 'windvane-cost',
  description: "windvane: this project's tokens and cost, today and over every recorded day",
}

export type LedgerEntry = {
  input: number
  output: number
  cache_read: number
  cache_creation: number
  turns: number
  cost_usd: number
}

function empty(): LedgerEntry {
  return { input: 0, output: 0, cache_read: 0, cache_creation: 0, turns: 0, cost_usd: 0 }
}

function num(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : 0
}

// A stored entry read defensively: a field missing or not a number is 0.
export function asEntry(v: unknown): LedgerEntry {
  const o = (v ?? {}) as Record<string, unknown>
  return {
    input: num(o.input),
    output: num(o.output),
    cache_read: num(o.cache_read),
    cache_creation: num(o.cache_creation),
    turns: num(o.turns),
    cost_usd: num(o.cost_usd),
  }
}

export function add(a: LedgerEntry, b: LedgerEntry): LedgerEntry {
  return {
    input: a.input + b.input,
    output: a.output + b.output,
    cache_read: a.cache_read + b.cache_read,
    cache_creation: a.cache_creation + b.cache_creation,
    turns: a.turns + b.turns,
    cost_usd: a.cost_usd + b.cost_usd,
  }
}

// The session's cost at the previous main turn. Module state: a reload starts
// over from the figure at its session.start, so nothing is counted twice.
let lastCost: number | undefined

// At session.start: the figure the ledger counts from.
export function costBaseline(cost: number | undefined): void {
  lastCost = cost
}

// One main-loop turn as a ledger entry: its four counts, and the session's
// cost since the previous main turn (0 when either figure is missing).
export function turnEntry(usage: TurnUsage | undefined, cost: number | undefined): LedgerEntry {
  const spent = cost !== undefined && lastCost !== undefined && cost >= lastCost ? cost - lastCost : 0
  if (cost !== undefined) lastCost = cost
  return {
    input: num(usage?.input_tokens),
    output: num(usage?.output_tokens),
    cache_read: num(usage?.cache_read_input_tokens),
    cache_creation: num(usage?.cache_creation_input_tokens),
    turns: 1,
    cost_usd: spent,
  }
}

// The local day of a time in milliseconds, YYYY-MM-DD.
export function localDay(ms: number): string {
  const d = new Date(ms)
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  return `${d.getFullYear()}-${mm}-${dd}`
}

export function ledgerKey(cwd: string, day: string): string {
  return `${PREFIX}${normalizePath(cwd)}:${day}`
}

// `ledger:<project>:<day>`: the project may hold colons (a drive letter), the
// day is the last ten characters.
function parseKey(key: string): { project: string; day: string } | undefined {
  if (!key.startsWith(PREFIX) || key.length < PREFIX.length + 12) return undefined
  const day = key.slice(-10)
  if (key[key.length - 11] !== ':' || !/^\d{4}-\d{2}-\d{2}$/.test(day)) return undefined
  return { project: key.slice(PREFIX.length, -11), day }
}

function grouped(n: number): string {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

function line(label: string, t: LedgerEntry): string {
  return (
    `${label}: ${grouped(t.turns)} turns · input ${grouped(t.input)} · output ${grouped(t.output)}` +
    ` · cache read ${grouped(t.cache_read)} · cache write ${grouped(t.cache_creation)} · $${t.cost_usd.toFixed(2)}`
  )
}

// /windvane-cost's answer for the ledger's project.
export async function report(host: Host, project: string): Promise<string> {
  const today = localDay(await host.now())
  let projectToday = empty()
  let projectAll = empty()
  let allToday = empty()
  for (const key of await host.storeKeys()) {
    const k = parseKey(key)
    if (!k || (k.project !== project && k.day !== today)) continue
    const entry = asEntry(await host.storeGet(key))
    if (k.project === project) projectAll = add(projectAll, entry)
    if (k.day === today) allToday = add(allToday, entry)
    if (k.project === project && k.day === today) projectToday = add(projectToday, entry)
  }
  return [
    `windvane ledger for ${project}, ${today}`,
    line('today, this project', projectToday),
    line('this project, all days', projectAll),
    line('today, all projects', allToday),
  ].join('\n')
}

files.hooks/pane.tsx:
// windvane: /windvane opens a pane with what windvane holds for this
// session, read from the store's own files:
//
// - the newest checkpoint record whole (the ring register.ts reads for the
//   status line): task, current step, completed, pending, files, warnings,
//   context needed, handoff note, goal;
// - the project's rules (the cwd's registered project and the ancestors it
//   inherits from, as the engine's project memory loader walks them);
// - the mistakes for the file the model last touched (Edit, Write, Read,
//   noted as the call is made), matched as the pre-edit check matches them.
//
// The pane reads the store when it opens and when Refresh is pressed.
// register.ts hooks the command, the tool calls that name the file and the
// pane's render, keeps the view in $.state and hands it here to draw; this
// module never holds `$`.
import type { Elements, RenderElement } from 'claude-code'

import type { PaneView, Pressure } from '../types'
import type { Host } from './engine'
import {
  ageText,
  mistakesFor,
  normalizePath,
  projectChain,
  readEntries,
  readLatest,
  readManifest,
  ringsFor,
  rulesOf,
  storePath,
} from './ring'
import type { Io } from './ring'

// The elements a drawing takes: the surface's table, as $.ui.resolve(e)
// hands it out.
export type Draw = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'>

// The tools whose file_path names the file the model last touched.
export const TOUCH_TOOLS = new Set(['Edit', 'Write', 'Read', 'MultiEdit', 'NotebookEdit'])
// The body rows asked for while the pane sits inline above the prompt: the
// summary, the checkpoint and the first rules without scrolling.
export const PANE_ROWS = 24
// The label column of the checkpoint's rows, and how many items of a list
// are shown before "and N more".
const LABEL = 11
const LIST_ROWS = 6

function oneLine(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, Math.max(0, max - 1))}…` : text
}

function basename(path: string): string {
  const parts = path.replace(/\\/g, '/').replace(/\/+$/, '').split('/')
  return parts[parts.length - 1] || path
}

function count(n: number, noun: string): string {
  return `${n} ${noun}${n === 1 ? '' : 's'}`
}

// Registered at session.start by register.ts.
export const PANE_COMMAND = {
  name: 'windvane',
  description: "Show windvane's checkpoint, rules and file mistakes in a pane",
}

function ioOf(host: Host): Io {
  return { read: p => host.read(p), exists: p => host.exists(p) }
}

function list(...values: (string[] | undefined)[]): string[] {
  for (const v of values) if (Array.isArray(v) && v.length) return v.filter(s => typeof s === 'string' && s !== '')
  return []
}

// The pane's body, from the store as it stands; `file` is the one the model
// last touched, when any.
export async function loadView(host: Host, file: string | undefined): Promise<PaneView> {
  const io = ioOf(host)
  const store = await host.store()
  const manifest = await readManifest(io, store)
  const cwd = normalizePath(await host.cwd())
  const root = normalizePath(await host.root())

  const rec = await readLatest(io, ringsFor(manifest, store, cwd, root), store)
  const chain = projectChain(manifest, cwd)
  const rules = rulesOf(await readEntries(io, store, chain))

  const fileChain = file ? projectChain(manifest, file) : []
  const mistakes = file ? mistakesFor(await readEntries(io, store, fileChain.length ? fileChain : chain), file) : []

  const view: PaneView = { loadedAt: Date.now(), store, project: chain[0]?.path, rules, file, mistakes }
  if (rec) {
    const task = rec.task_description ?? ''
    const handoff = rec.handoff_summary || rec.summary || ''
    view.checkpoint = {
      created: rec.created ?? rec.timestamp,
      kind: rec.kind,
      task_id: rec.task_id,
      project_path: rec.project_path,
      task_description: task || undefined,
      current_step: rec.current_step || undefined,
      completed: list(rec.completed_steps),
      pending: list(rec.next_steps, rec.pending_steps),
      files: list(rec.files_in_progress, rec.files_involved),
      warnings: list(rec.warnings, rec.handoff_warnings),
      context_needed: list(rec.context_needed, rec.handoff_context_needed),
      handoff: handoff && handoff !== task ? handoff : undefined,
      goal: rec.goal || undefined,
    }
  }
  return view
}

// What the pane draws from: the view as loaded (null before the first
// read), the status line's figures, whether the band is hidden (its Show
// button then appears), the body's width in columns and the time.
export type PaneData = {
  view: PaneView | null
  figures: Pressure | null
  hidden: boolean
  bodyColumns: number | undefined
  nowMs: number
}

// The buttons' work, done by register.ts: a fresh read of the store, and
// the band shown again.
export type PaneActions = { refresh: () => void; showBand: () => void }

// The pane's tree.
export function drawPane(ui: Draw, data: PaneData, act: PaneActions): RenderElement {
  const { Box, Button, Text } = ui
  const { view, figures, hidden, nowMs: now } = data

  // The body's width, so prose that may take two rows is cut after them;
  // every other row is cut at the edge by the surface, with an ellipsis.
  const width = Math.max(24, data.bodyColumns || 80)
  const rows: RenderElement[] = []
  let n = 0
  type Style = { bold?: boolean; dimColor?: boolean }
  const row = (text: string, style: Style = {}) =>
    rows.push(
      <Text key={`l${n++}`} wrap="truncate-end" {...style}>
        {text}
      </Text>,
    )
  const gap = () => row(' ')
  const pad = (label: string) => label.padEnd(LABEL)
  // A labelled row of prose: up to two rows, then an ellipsis.
  const prose = (label: string, text: string) =>
    rows.push(
      <Text key={`l${n++}`} wrap="wrap">
        {`  ${pad(label)}${clip(oneLine(text), 2 * width - LABEL - 4)}`}
      </Text>,
    )
  // A labelled list: the count in the label, one item per row, the first
  // LIST_ROWS of them.
  const items = (label: string, list: string[]) => {
    row(`  ${pad(`${label} ${list.length}`)}${oneLine(list[0] ?? '')}`)
    for (const s of list.slice(1, LIST_ROWS)) row(`  ${pad('')}${oneLine(s)}`)
    if (list.length > LIST_ROWS) row(`  ${pad('')}and ${list.length - LIST_ROWS} more`, { dimColor: true })
  }

  // One row of figures: the fill, the checkpoint age, the band, and what
  // the pane holds below.
  const summary = [
    figures ? `ctx ${figures.percent ?? '?'}%` : undefined,
    figures ? ageText(figures.checkpointCreated, now) : undefined,
    figures?.inBand ? 'checkpoint now' : undefined,
    view ? count(view.rules.length, 'rule') : undefined,
    view?.file ? `${count(view.mistakes.length, 'mistake')} for ${basename(view.file)}` : undefined,
  ].filter((s): s is string => s !== undefined)
  if (summary.length) row(summary.join(' · '), { dimColor: true })

  if (!view) {
    row('Nothing read yet: press Refresh.', { dimColor: true })
  } else {
    const c = view.checkpoint
    gap()
    if (!c) {
      row('Checkpoint · none in the ring', { bold: true })
    } else {
      const meta = [c.kind ?? 'auto', `${ageText(c.created, now).replace('ckpt ', '')} ago`, c.task_id, c.project_path ? basename(c.project_path) : undefined]
      row(`Checkpoint · ${meta.filter(Boolean).join(' · ')}`, { bold: true })
      if (c.task_description) prose('Task', c.task_description)
      if (c.current_step) prose('Step', c.current_step)
      if (c.completed.length) items('Done', c.completed)
      if (c.pending.length) items('Pending', c.pending)
      if (c.files.length) row(`  ${pad(`Files ${c.files.length}`)}${c.files.map(basename).join(', ')}`)
      if (c.warnings.length) items('Warnings', c.warnings)
      if (c.context_needed.length) items('Needed', c.context_needed)
      if (c.handoff) prose('Handoff', c.handoff)
      if (c.goal) prose('Goal', c.goal)
    }

    gap()
    row(`Rules · ${view.rules.length}${view.project ? ` · ${basename(view.project)}` : ''}`, { bold: true })
    if (!view.rules.length) row('  none', { dimColor: true })
    for (const r of view.rules) row(`  [${r.id}] ${oneLine(r.content)}`)

    gap()
    row(view.file ? `Mistakes · ${view.mistakes.length} · ${basename(view.file)}` : 'Mistakes', { bold: true })
    if (!view.file) row('  no file touched yet this session', { dimColor: true })
    else if (!view.mistakes.length) row('  none', { dimColor: true })
    for (const m of view.mistakes) row(`  [${m.id}] ${oneLine(m.content)}`)
  }

  return (
    <Box key="windvane-pane" flexDirection="column">
      <Box key="windvane-actions" flexDirection="row">
        <Button key="windvane-refresh" label="Refresh" onPress={act.refresh} />
        {hidden && <Button key="windvane-show-band" label="Show band" onPress={act.showBand} />}
      </Box>
      {rows}
    </Box>
  )
}

files.hooks/remember.ts:
// windvane: /remember stores the text the person selected in the
// transcript as a DECISION in windvane, for the session's project.
//
// The store is written by the engine, never by the mod: the command runs
// `python -m windvane.remember`, which files the entry through the same
// writer the memory tool's remember operation and the miner's decisions use.
// The text goes in on stdin, so no quoting rule of any shell touches it.
// The interpreter is WINDVANE_PYTHON, else the plugin's python option, else
// `python` on PATH; the store is the one the rest of the mod reads
// (WINDVANE_DIR, else ~/.windvane).
//
// register.ts registers the command, hooks its run with the selection and
// the file the model last touched; this module never holds `$`.
import { clip, engineEnv, lastJsonLine, pythonHint, type Host } from './engine'

const REMEMBER_TIMEOUT_MS = 30_000

// Registered at session.start by register.ts.
export const REMEMBER_COMMAND = {
  name: 'remember',
  description: 'Store the selected transcript text in windvane as a decision',
}

type Reply = { stored?: boolean; id?: string; project?: string; message?: string; error?: string }

// The command's answer for the selected text; `file` is the one the model
// last touched, when any.
export async function remember(host: Host, configured: string, text: string, file: string | null | undefined): Promise<string> {
  const python = await host.python(configured)
  const store = await host.store()
  const argv = [python, '-m', 'windvane.remember', '--project', await host.cwd(), '--kind', 'decision']
  if (file) argv.push('--file', file)

  let run
  try {
    run = await host.run(argv, {
      stdin: text,
      env: engineEnv(host.pluginRoot, store),
      timeoutMs: REMEMBER_TIMEOUT_MS,
    })
  } catch (err) {
    return `Not remembered: ${pythonHint(python, err)}`
  }
  const reply = (lastJsonLine(run.stdout) ?? {}) as Reply
  if (run.exitCode !== 0 || reply.error) {
    const why = reply.error || clip(run.stderr, 200) || `exit ${run.exitCode}`
    return `Not remembered: ${why}`
  }
  if (!reply.stored) return `Already in windvane${reply.project ? ` for ${reply.project}` : ''}: ${reply.message ?? ''}`.trim()
  return `Remembered as a decision${reply.project ? ` for ${reply.project}` : ''}${reply.id ? ` [${reply.id}]` : ''}: ${clip(text, 120)}`
}

files.hooks/setup.ts:
// windvane: the first-run offer of the semantic tier. A small embedding
// model (sentence-transformers, bge-base) lets memory and session search
// find paraphrases a keyword match cannot: on a store of 200k chunks,
// hybrid search found the right chunk about six times as often as keyword
// alone. The extra is not installed with the plugin (torch is large) and
// the `semantic` row is off by default, so the first interactive session
// asks once: install and turn on, turn on (the extra is already there),
// not now (asked again in a week) or never. The answer lives in $.store
// under `semanticOffer`. A -p run has no one to ask and is never asked.
//
// This file holds the decisions; register.ts does the $ work at
// session.start, as for the other pieces.

export const SEMANTIC_OFFER_KEY = 'semanticOffer'
export const SEMANTIC_ROW = 'windvane.semantic'
export const EXTRA_PACKAGES = ['sentence-transformers>=2.7.0', 'numpy>=1.24.0']
export const RETRY_AFTER_MS = 7 * 24 * 3600 * 1000
export const CHECK_TIMEOUT_MS = 60_000
// The host caps a run at ten minutes; a slower install ends with the toast
// that says to pip install by hand.
export const INSTALL_TIMEOUT_MS = 600_000

export type Offer = { answer: 'done' | 'never' | 'later'; at: number }

export function recordOf(answer: Offer['answer'], now = Date.now()): Offer {
  return { answer, at: now }
}

// Is the question due? Never after a yes or a never; a week after a not now.
export function offerDue(prior: unknown, now: number): boolean {
  const p = prior as Partial<Offer> | undefined
  if (!p || typeof p !== 'object') return true
  if (p.answer === 'done' || p.answer === 'never') return false
  if (p.answer === 'later') return now - (typeof p.at === 'number' ? p.at : 0) >= RETRY_AFTER_MS
  return true
}

// The semantic row as /config lists it; a userConfig value can arrive as a string.
export function rowOnFrom(rows: ReadonlyArray<{ key: string; value: unknown }>): boolean {
  const row = rows.find(r => r.key === SEMANTIC_ROW)
  return row?.value === true || row?.value === 'true'
}

// The engine's own check of the extra: the modules are looked up, torch is
// not imported.
export function checkArgv(python: string): string[] {
  return [python, '-c', 'from windvane import semantic; print(int(semantic.available()))']
}

export function extraInstalledFrom(run: { exitCode: number; stdout: string }): boolean {
  return run.exitCode === 0 && run.stdout.trim().endsWith('1')
}

export function installArgv(python: string): string[] {
  return [python, '-m', 'pip', 'install', ...EXTRA_PACKAGES]
}

// The question for the state found, or undefined when both are in place.
export function offerFor(rowOn: boolean, installed: boolean): { act: string; question: string } | undefined {
  if (rowOn && installed) return undefined
  if (rowOn) {
    return {
      act: 'Install',
      question:
        'windvane: the semantic row is on but the extra it needs is not installed. Install it (sentence-transformers and numpy, several hundred MB) so memory and session search use the embedding model?',
    }
  }
  if (installed) {
    return {
      act: 'Turn on',
      question:
        'windvane: the semantic extra is installed but the semantic row is off. Turn it on so memory and session search use the embedding model?',
    }
  }
  return {
    act: 'Install and turn on',
    question:
      'windvane can search memory and past sessions with a small embedding model, which finds paraphrases a keyword match misses. Install the extra (sentence-transformers and numpy, several hundred MB) and turn the semantic row on?',
  }
}

files.hooks/ring.ts:
// windvane: windvane's store as the mod reads it. Shared by the status line
// (register.ts), the pane (pane.tsx), the band (band.tsx) and /remember.
//
// Everything here reads the files windvane's Python engine writes; nothing
// is written. The layout is the engine's: manifest.json maps a normalized
// project path to a hash, projects/<hash>/memory.json holds the entries,
// projects/<hash>/latest_handoff.json the newest ring record.
//
// The engine follows $ only into functions of the file that holds the hook,
// never across an import, so the readers here take an Io: two closures the
// calling module builds over its own $ (`ioOf` in each).

// File reads, as $.fs answers them.
export type Io = { read(path: string): Promise<string>; exists(path: string): Promise<boolean> }

export type Manifest = { projects?: Record<string, { hash?: string }> }

// One ring record. The ring writes one name per concept (next_steps,
// files_in_progress, warnings, context_needed); records written before that
// carry the checkpoint-side twins, so every reader takes either.
export type RingRecord = {
  created?: number
  timestamp?: number
  kind?: string
  task_id?: string
  session_id?: string
  project_path?: string
  task_description?: string
  summary?: string
  handoff_summary?: string
  current_step?: string
  completed_steps?: string[]
  next_steps?: string[]
  pending_steps?: string[]
  files_in_progress?: string[]
  files_involved?: string[]
  warnings?: string[]
  handoff_warnings?: string[]
  context_needed?: string[]
  handoff_context_needed?: string[]
  goal?: string
}

// A memory.json entry, the fields the mod reads.
export type MemoryEntry = {
  id?: string
  content?: string
  category?: string
  relevance?: number
  created_at?: number
  archived_at?: number
  related_files?: string[] | string
}

// The engine's path normalization: forward slashes, lowercase drive letter.
export function normalizePath(p: string): string {
  let s = p.replace(/\\/g, '/')
  if (s.length >= 2 && s[1] === ':') s = s.charAt(0).toLowerCase() + s.slice(1)
  return s
}

// The store: WINDVANE_DIR, else ~/.windvane, from the three variables as
// $.env.get answers them (the engine's config.store_dir).
export function storePath(override: string | undefined, userProfile: string | undefined, home: string | undefined): string {
  const base = userProfile ?? home ?? ''
  return ((override && override.trim()) || `${base}/.windvane`).replace(/\\/g, '/')
}

export async function readManifest(io: Io, store: string): Promise<Manifest> {
  try {
    return JSON.parse(await io.read(`${store}/manifest.json`)) as Manifest
  } catch {
    return {}
  }
}

// The newest checkpoint record among the rings that can hold this session's
// saves: the current directory's project, the session root's, and every
// registered project beneath the root (windvane files a save under the work
// project, which may sit below the directory the session was opened in).
// The global ring is the last resort.
export async function readLatest(io: Io, rings: string[], store: string): Promise<RingRecord | undefined> {
  let best: RingRecord | undefined
  for (const p of [...rings, `${store}/checkpoints/latest_handoff.json`]) {
    if (!p) continue
    try {
      if (!(await io.exists(p))) continue
      const rec = JSON.parse(await io.read(p)) as RingRecord
      if (!best || (rec.created ?? 0) > (best.created ?? 0)) best = rec
    } catch {
      // unreadable: try the next
    }
  }
  return best
}

// The rings worth reading, from the store's manifest (normalized path to hash).
export function ringsFor(manifest: Manifest, store: string, cwd: string, root: string): string[] {
  const out: string[] = []
  const projects = manifest.projects ?? {}
  for (const [path, info] of Object.entries(projects)) {
    if (!info?.hash) continue
    if (path === cwd || path === root || path.startsWith(root + '/') || path.startsWith(cwd + '/')) {
      out.push(`${store}/projects/${info.hash}/latest_handoff.json`)
    }
  }
  return out
}

// The registered projects at or above `path`, deepest first: the project a
// path belongs to, then the ancestors whose rules and mistakes it inherits
// (the engine's project memory loader walks the same way).
export function projectChain(manifest: Manifest, path: string): { path: string; hash: string }[] {
  const p = normalizePath(path)
  const out: { path: string; hash: string }[] = []
  for (const [proj, info] of Object.entries(manifest.projects ?? {})) {
    if (!info?.hash) continue
    if (p === proj || p.startsWith(proj.endsWith('/') ? proj : proj + '/')) out.push({ path: proj, hash: info.hash })
  }
  return out.sort((a, b) => b.path.length - a.path.length)
}

// The entries of every project in the chain, the deepest copy of an id kept.
export async function readEntries(io: Io, store: string, chain: { hash: string }[]): Promise<MemoryEntry[]> {
  const seen = new Set<string>()
  const out: MemoryEntry[] = []
  for (const { hash } of chain) {
    let entries: MemoryEntry[] = []
    try {
      const data = JSON.parse(await io.read(`${store}/projects/${hash}/memory.json`)) as { entries?: MemoryEntry[] }
      entries = data.entries ?? []
    } catch {
      continue
    }
    for (const e of entries) {
      const id = e.id ?? ''
      if (id && seen.has(id)) continue
      if (id) seen.add(id)
      out.push(e)
    }
  }
  return out
}

// The project's rules as the engine lists them: most relevant first.
export function rulesOf(entries: MemoryEntry[]): { id: string; content: string }[] {
  return entries
    .filter(e => e.category === 'rule')
    .sort((a, b) => (b.relevance ?? 5) - (a.relevance ?? 5))
    .map(e => ({ id: e.id ?? '', content: e.content ?? '' }))
}

// The engine's generic basenames: names every project has, where only a
// full-path mention says which file is meant.
const GENERIC_BASENAMES = new Set([
  '__init__.py', '__main__.py', '__init__.ts', 'index.js', 'index.ts', 'index.tsx', 'mod.rs', 'setup.py',
  'conftest.py', 'types.ts', 'readme.md', 'claude.md', 'agents.md', 'changelog.md', 'errors.md',
  'learnings.md', 'handoff.md', 'notes.md', 'todo.md', 'plan.md', 'license', 'pyproject.toml', 'setup.cfg',
  'requirements.txt', 'package.json', 'tsconfig.json', 'cargo.toml', 'makefile',
])

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

// The pre-edit check's matching, as the engine runs it: the live mistakes
// (not archived) that name this file, newest first. A specific
// basename matches as a word in the text; a generic one needs the full path;
// a related_files entry naming the file matches either way.
export function mistakesFor(entries: MemoryEntry[], file: string): { id: string; content: string }[] {
  const full = normalizePath(file).toLowerCase()
  const name = full.slice(full.lastIndexOf('/') + 1)
  const generic = GENERIC_BASENAMES.has(name)
  const pattern = new RegExp('(?:^|[\\s/\\\\:])' + escapeRegExp(name) + '(?:[\\s:,.]|$)')
  const out: { id: string; content: string; created: number }[] = []
  for (const e of entries) {
    if (e.archived_at) continue
    const content = e.content ?? ''
    const isMistake = content.toUpperCase().startsWith('MISTAKE:') || e.category === 'mistake'
    if (!isMistake) continue
    const text = content.replace(/^MISTAKE: ?/i, '')
    const lower = content.replace(/\\/g, '/').toLowerCase()
    const related = (Array.isArray(e.related_files) ? e.related_files : e.related_files ? [e.related_files] : []).map(
      f => normalizePath(f).toLowerCase(),
    )
    const byFile = related.some(f => f === full || (!generic && f.endsWith('/' + name)))
    const byText = generic ? lower.includes(full) : pattern.test(content.toLowerCase())
    if (byFile || byText) out.push({ id: e.id ?? '', content: text, created: e.created_at ?? 0 })
  }
  return out.sort((a, b) => b.created - a.created).map(({ id, content }) => ({ id, content }))
}

export function ageText(created?: number, nowMs: number = Date.now()): string {
  if (!created) return 'ckpt none'
  const mins = Math.max(0, Math.round((nowMs / 1000 - created) / 60))
  if (mins < 60) return `ckpt ${mins}m`
  if (mins < 48 * 60) return `ckpt ${(mins / 60).toFixed(1)}h`
  return `ckpt ${Math.round(mins / 1440)}d`
}

files.hooks/strict.ts:
// windvane: /windvane-strict seeds the strict rule pack into this project.
//
// The default pack (the working rules) is seeded by the engine on a fresh
// session start. The strict pack (style and workflow rules) is opt-in: the
// strict_pack option seeds it into every new project, this command into the
// session's project once. The engine does the work, `python -m
// windvane.rules seed --project <cwd> --strict`, and prints one JSON line;
// the command shows its summary.
//
// register.ts registers the command and hooks its run; this module never
// holds `$`.
import { clip, engineEnv, lastJsonLine, pythonHint, type Host } from './engine'

const STRICT_TIMEOUT_MS = 30_000

// Registered at session.start by register.ts.
export const STRICT_COMMAND = {
  name: 'windvane-strict',
  description: 'windvane: seed the strict rule pack (style and workflow rules) into this project',
}

// The JSON line in one sentence: its summary, else its plain fields.
export function summaryOf(reply: Record<string, unknown>): string {
  if (typeof reply.summary === 'string' && reply.summary.trim()) return reply.summary.trim()
  const parts = Object.entries(reply)
    .filter(([, v]) => typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean')
    .map(([k, v]) => `${k}: ${String(v)}`)
  return parts.length > 0 ? parts.join(' · ') : 'done'
}

// The command's answer.
export async function seedStrict(host: Host, configured: string): Promise<string> {
  const python = await host.python(configured)
  const store = await host.store()
  const project = await host.cwd()
  let run
  try {
    run = await host.run([python, '-m', 'windvane.rules', 'seed', '--project', project, '--strict'], {
      cwd: project,
      env: engineEnv(host.pluginRoot, store),
      timeoutMs: STRICT_TIMEOUT_MS,
    })
  } catch (err) {
    return `Strict pack not seeded: ${pythonHint(python, err)}`
  }
  const reply = lastJsonLine(run.stdout)
  if (run.exitCode !== 0 || !reply || typeof reply.error === 'string') {
    const why = (typeof reply?.error === 'string' && reply.error) || clip(run.stderr, 200) || `exit ${run.exitCode}`
    return `Strict pack not seeded: ${why}`
  }
  return `Strict pack: ${summaryOf(reply)}`
}

files.hooks/tools.ts:
// windvane: the tools the model calls, served by the mod.
//
// register.ts declares each tool in TOOL_SPECS with $.tool.register at
// session.start; the engine lists it to the model as mcp__windvane__<name>.
// A call is served here, from a tool.call hook matched on the tool's full
// name. Its arguments go to the engine's tool handlers as one JSON request,
// `{ tool, arguments, env }`:
//
// 1. first to the daemon, `POST http://127.0.0.1:<port>/tool` with the
//    headers `X-Windvane-Hook: 1` and `X-Windvane-Token`, the port and the
//    token read from `<store>/daemon_port` and `<store>/daemon_token`
//    (warm imports, one handler instance across calls);
// 2. when the daemon is down (no port file, a refused connection, a non-200,
//    a body that is not an answer), to `python -m windvane.tools` with the
//    same request on stdin.
//
// `env` carries the session id (the engine keys the draft and the hook
// state by it) and the session's working directory as CLAUDE_PROJECT_DIR:
// the daemon runs in the plugin folder, and a call that names no project
// must be filed under the session's, never the daemon's.
//
// Either answers `{ text, isError, ms }`. The model reads `text`; an error
// is returned as a deny, which the model receives as an error result with
// the reason. A daemon request that timed out may still have run, so it is
// not retried through the subprocess: the model is told to check first.
//
// compact_now: the engine banks the drafted checkpoint and answers. The
// compaction itself cannot run here: $.session.compact() rejects while a
// turn runs, and the model's turn goes on after a tool result. register.ts
// watches the call and compacts at the turn boundary, from a timer, the way
// it compacts inside the checkpoint band.
//
// register.ts hooks each tool's call and answers with what serve says; this
// module never holds `$`.
import type { Timer, ToolSpec } from 'claude-code'

import { PLUGIN, clip, engineEnv, lastJsonLine, pythonHint, type Host, type Settings } from './engine'

export const TOOL_TIMEOUT_MS = 60_000

// What compact_now's answer adds for the model.
export const COMPACT_NOTE = `${PLUGIN}: the conversation compacts as soon as this turn ends; end the turn now.`

const PROJECT = {
  type: 'string',
  description: 'The project directory; leave it out and windvane uses the project this session is working in.',
} as const
const LIST = { type: 'array', items: { type: 'string' } } as const

const CHECKPOINT_FIELDS = {
  operation: {
    type: 'string',
    enum: ['save', 'restore', 'list'],
    description:
      'save banks the task state (with no other argument it accepts the record the recorder drafted from the session; a field given amends that field); restore reads one back; list shows the ring newest first.',
  },
  task_description: { type: 'string', description: 'save: what the task is, in one sentence.' },
  current_step: { type: 'string', description: 'save: the step in progress.' },
  completed_steps: { ...LIST, description: 'save: the steps done.' },
  pending_steps: { ...LIST, description: 'save: the steps left, next first.' },
  files_involved: { ...LIST, description: 'save: the files being worked on.' },
  handoff_summary: { type: 'string', description: 'save: the note the next session reads first.' },
  handoff_warnings: { ...LIST, description: 'save: what the next session must not do.' },
  handoff_context_needed: { ...LIST, description: 'save: what the next session should read first.' },
  index: { type: 'integer', description: 'restore: which record, 0 = newest (see list).' },
  project_path: PROJECT,
} as const

const COMPACT_FIELDS = {
  project_path: PROJECT,
} as const

const MEMORY_FIELDS = {
  operation: {
    type: 'string',
    enum: [
      'remember',
      'recall',
      'recent',
      'search',
      'archive_search',
      'forget',
      'add_rule',
      'list_rules',
      'modify',
      'delete',
      'promote',
      'archive',
      'restore',
      'list_mistakes',
      'acknowledge_mistake',
      'set_detector',
    ],
    description:
      'remember stores a discovery; recall lists the project memory; recent lists the newest entries first; search finds entries by query; archive_search finds archived entries by query; forget clears the project memory; add_rule stores a permanent rule (with reason); list_rules lists them; modify, delete, promote (to a rule), archive, restore and acknowledge_mistake act on one entry by id; list_mistakes lists the tracked mistakes; set_detector attaches a detector to a rule.',
  },
  content: { type: 'string', description: 'remember / add_rule / modify: the text.' },
  reason: { type: 'string', description: 'add_rule / promote: why the rule exists.' },
  query: { type: 'string', description: 'search / archive_search: what to look for.' },
  memory_id: { type: 'string', description: 'modify / delete / promote / restore / acknowledge_mistake / set_detector: the id shown in brackets.' },
  limit: { type: 'integer', description: 'recall / recent / search / archive_search / list_rules / list_mistakes: how many.' },
  detector: {
    type: 'object',
    description:
      'add_rule / set_detector: when the rule applies, so its matches are recorded. Keys: tools (tool names, empty = any), command (regex against a shell command), paths (globs against an edited path), input (regex against the tool input JSON), note. {} clears.',
  },
  project_path: PROJECT,
} as const

const LOG_FIELDS = {
  operation: {
